-- Phase 4 (Step 22): replace PAYPAL with KLARNA on the payments.payment_method
-- CHECK constraint. Dropping and re-adding the column also drops the autogenerated
-- CHECK constraint; the new inline CHECK matches the updated PaymentMethod enum
-- and the column Hibernate ddl-auto would generate.
alter table payments
    drop column payment_method;

alter table payments
    add column payment_method varchar(255) not null check ((payment_method in ('MBWAY','MULTIBANCO','CREDIT_CARD','KLARNA')));